(window.__quranSurahs=window.__quranSurahs||{})[84]={"nomPhon":"Al-Inshiqaaq","versets":{"1":{"text":"Quand le ciel se déchirera","arabe":"إِذَا ٱلسَّمَآءُ ٱنشَقَّتْ"},"2":{"text":"et obéira à son Seigneur - et fera ce qu'il doit faire -","arabe":"وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ"},"3":{"text":"et que la terre sera nivelée,","arabe":"وَإِذَا ٱلْأَرْضُ مُدَّتْ"},"4":{"text":"et qu'elle rejettera ce qui est en son sein (les morts) et se videra,","arabe":"وَأَلْقَتْ مَا فِيهَا وَتَخَلَّتْ"},"5":{"text":"et qu'elle obéira à son Seigneur - et fera ce qu'elle doit faire -","arabe":"وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ"},"6":{"text":"O homme! Toi qui t'efforces vers ton Seigneur sans relâche, tu Le rencontreras alors.","arabe":"يَٰٓأَيُّهَا ٱلْإِنسَٰنُ إِنَّكَ كَادِحٌ إِلَىٰ رَبِّكَ كَدْحًۭا فَمُلَٰقِيهِ"},"7":{"text":"Celui qui recevra son livre en sa main droite,","arabe":"فَأَمَّا مَنْ أُوتِىَ كِتَٰبَهُۥ بِيَمِينِهِۦ"},"8":{"text":"sera soumis à un jugement facile,","arabe":"فَسَوْفَ يُحَاسَبُ حِسَابًۭا يَسِيرًۭا"},"9":{"text":"et retournera réjoui auprès de sa famille","arabe":"وَيَنقَلِبُ إِلَىٰٓ أَهْلِهِۦ مَسْرُورًۭا"},"10":{"text":"Quant à celui qui recevra son livre derrière son dos,","arabe":"وَأَمَّا مَنْ أُوتِىَ كِتَٰبَهُۥ وَرَآءَ ظَهْرِهِۦ"},"11":{"text":"il invoquera la destruction sur lui-même,","arabe":"فَسَوْفَ يَدْعُوا۟ ثُبُورًۭا"},"12":{"text":"et il brûlera dans un feu ardent.","arabe":"وَيَصْلَىٰ سَعِيرًا"},"13":{"text":"Car il était tout joyeux parmi les siens,","arabe":"إِنَّهُۥ كَانَ فِىٓ أَهْلِهِۦ مَسْرُورًا"},"14":{"text":"et il pensait que jamais il ne ressusciterait","arabe":"إِنَّهُۥ ظَنَّ أَن لَّن يَحُورَ"},"15":{"text":"Mais si! Certes, son Seigneur l'observait parfaitement.","arabe":"بَلَىٰٓ إِنَّ رَبَّهُۥ كَانَ بِهِۦ بَصِيرًۭا"},"16":{"text":"Non!... Je jure par le crépuscule,","arabe":"فَلَآ أُقْسِمُ بِٱلشَّفَقِ"},"17":{"text":"et par la nuit et ce qu'elle enveloppe,","arabe":"وَٱلَّيْلِ وَمَا وَسَقَ"},"18":{"text":"et par la lune quand elle devient pleine lune!","arabe":"وَٱلْقَمَرِ إِذَا ٱتَّسَقَ"},"19":{"text":"Vous passerez, certes, par des états successifs!","arabe":"لَتَرْكَبُنَّ طَبَقًا عَن طَبَقٍۢ"},"20":{"text":"Qu'ont-ils à ne pas croire?","arabe":"فَمَا لَهُمْ لَا يُؤْمِنُونَ"},"21":{"text":"et à ne pas se prosterner quand le Coran leur est lu?","arabe":"وَإِذَا قُرِئَ عَلَيْهِمُ ٱلْقُرْءَانُ لَا يَسْجُدُونَ ۩"},"22":{"text":"Mais ceux qui ne croient pas, le traitent plutôt de mensonge.","arabe":"بَلِ ٱلَّذِينَ كَفَرُوا۟ يُكَذِّبُونَ"},"23":{"text":"Or, Allah sait bien ce qu'ils dissimulent.","arabe":"وَٱللَّهُ أَعْلَمُ بِمَا يُوعُونَ"},"24":{"text":"Annonce-leur donc un châtiment douloureux.","arabe":"فَبَشِّرْهُم بِعَذَابٍ أَلِيمٍ"},"25":{"text":"Sauf ceux qui croient et accomplissent les bonnes œuvres: à eux une récompense jamais interrompue.","arabe":"إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍۭ"}}};